"""Permission-checked PDF download; generated bytes are not saved on the server."""
from fastapi import APIRouter, Depends, Query, Response
from backend.auth import require_patients, patient_access
from backend.routes.clinical import clinical, authorize
from backend.routes.workflow import known_patient
from backend.routes.patients import selected_service, ModelProfile
from backend.services.auth_service import get_auth_store
from backend.services.patient_pdf import make_patient_pdf
router=APIRouter(tags=['patient reports'])

@router.get('/patients/{patient_id}/summary.pdf')
def summary_pdf(patient_id:str, as_of_minutes:int=Query(1440,ge=0,le=1440), model_profile:ModelProfile='original', principal=Depends(require_patients)):
    patient_access(principal,patient_id);known_patient(patient_id)
    data=clinical(patient_id,as_of_minutes,model_profile,principal)
    detail=selected_service(model_profile).get_patient_detail(patient_id,as_of_minutes=as_of_minutes).model_dump()
    content=make_patient_pdf(detail,data,get_auth_store().clock())
    with get_auth_store().db() as db:
        authorize(db,principal,patient_id,{'admin','doctor','nurse','coordinator'})
    return Response(content,media_type='application/pdf',headers={'Content-Disposition':f'attachment; filename="{patient_id}-research-summary.pdf"','Cache-Control':'no-store'})
